-- zetaris/30_case.sql · q_case in one Postgres round trip (perf). Owner: nexus-2.
-- GENERATED by `python -m app.adapters.case_bundle`; tests/engines/test_case_bundle.py checks it.
-- A native-SQL datasource view over sb: Zetaris pushes `WHERE crime_id = ...` into it (verified with EXPLAIN on
-- crime_features_v), so q_case becomes one JDBC trip instead of six. register.py fills {{city:timezone}}.

CREATE DATASOURCE VIEW case_bundle_v FROM sb AS SELECT c.crime_id, c.source, c.source_row_id, c.station_id, c.fir_no, c.category, c.sub_type, c.sections::text AS sections, CASE WHEN c.occurred_from IS NULL THEN NULL ELSE to_char((c.occurred_from AT TIME ZONE '{{city:timezone}}'), 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_part('microseconds', (c.occurred_from AT TIME ZONE '{{city:timezone}}'))::bigint % 1000000 = 0 THEN '' ELSE '.' || rtrim(to_char((c.occurred_from AT TIME ZONE '{{city:timezone}}'), 'US'), '0') END || CASE WHEN ((c.occurred_from AT TIME ZONE '{{city:timezone}}') - (c.occurred_from AT TIME ZONE 'UTC')) < interval '0' THEN '-' || to_char(-((c.occurred_from AT TIME ZONE '{{city:timezone}}') - (c.occurred_from AT TIME ZONE 'UTC')), 'HH24:MI') ELSE '+' || to_char(((c.occurred_from AT TIME ZONE '{{city:timezone}}') - (c.occurred_from AT TIME ZONE 'UTC')), 'HH24:MI') END END AS occurred_from, CASE WHEN c.occurred_to IS NULL THEN NULL ELSE to_char((c.occurred_to AT TIME ZONE '{{city:timezone}}'), 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_part('microseconds', (c.occurred_to AT TIME ZONE '{{city:timezone}}'))::bigint % 1000000 = 0 THEN '' ELSE '.' || rtrim(to_char((c.occurred_to AT TIME ZONE '{{city:timezone}}'), 'US'), '0') END || CASE WHEN ((c.occurred_to AT TIME ZONE '{{city:timezone}}') - (c.occurred_to AT TIME ZONE 'UTC')) < interval '0' THEN '-' || to_char(-((c.occurred_to AT TIME ZONE '{{city:timezone}}') - (c.occurred_to AT TIME ZONE 'UTC')), 'HH24:MI') ELSE '+' || to_char(((c.occurred_to AT TIME ZONE '{{city:timezone}}') - (c.occurred_to AT TIME ZONE 'UTC')), 'HH24:MI') END END AS occurred_to, CASE WHEN c.reported_at IS NULL THEN NULL ELSE to_char((c.reported_at AT TIME ZONE '{{city:timezone}}'), 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_part('microseconds', (c.reported_at AT TIME ZONE '{{city:timezone}}'))::bigint % 1000000 = 0 THEN '' ELSE '.' || rtrim(to_char((c.reported_at AT TIME ZONE '{{city:timezone}}'), 'US'), '0') END || CASE WHEN ((c.reported_at AT TIME ZONE '{{city:timezone}}') - (c.reported_at AT TIME ZONE 'UTC')) < interval '0' THEN '-' || to_char(-((c.reported_at AT TIME ZONE '{{city:timezone}}') - (c.reported_at AT TIME ZONE 'UTC')), 'HH24:MI') ELSE '+' || to_char(((c.reported_at AT TIME ZONE '{{city:timezone}}') - (c.reported_at AT TIME ZONE 'UTC')), 'HH24:MI') END END AS reported_at, c.lat, c.lon, c.address, c.ward_no, c.h3_r9, c.h3_r8, c.geohash7, c.week, c.severity::int AS severity, c.property::text AS property, c.weapon, c.offenders_described::text AS offenders_described, c.victims::text AS victims, c.status, c.narrative, c.synthetic, coalesce((SELECT json_agg(json_build_object('role', v.role, 'type', v.vehicle_type, 'plate', v.plate_pattern, 'make_model', v.make_model, 'colour', v.colour) ORDER BY v.role, v.plate_pattern) FROM public.crime_vehicles v WHERE v.crime_id = c.crime_id)::text, '[]') AS vehicles, coalesce((SELECT json_agg(json_build_object('statement_id', s.statement_id, 'witness_ref', s.witness_ref, 'mode', s.mode, 'text', s.text, 'recorded_at', CASE WHEN s.recorded_at IS NULL THEN NULL ELSE to_char((s.recorded_at AT TIME ZONE '{{city:timezone}}'), 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_part('microseconds', (s.recorded_at AT TIME ZONE '{{city:timezone}}'))::bigint % 1000000 = 0 THEN '' ELSE '.' || rtrim(to_char((s.recorded_at AT TIME ZONE '{{city:timezone}}'), 'US'), '0') END || CASE WHEN ((s.recorded_at AT TIME ZONE '{{city:timezone}}') - (s.recorded_at AT TIME ZONE 'UTC')) < interval '0' THEN '-' || to_char(-((s.recorded_at AT TIME ZONE '{{city:timezone}}') - (s.recorded_at AT TIME ZONE 'UTC')), 'HH24:MI') ELSE '+' || to_char(((s.recorded_at AT TIME ZONE '{{city:timezone}}') - (s.recorded_at AT TIME ZONE 'UTC')), 'HH24:MI') END END) ORDER BY s.statement_id) FROM public.statements s WHERE s.crime_id = c.crime_id)::text, '[]') AS statements, coalesce((SELECT json_agg(json_build_object('evidence_id', e.evidence_id, 'kind', e.kind, 'storage_path', e.storage_path, 'captured_at', CASE WHEN e.captured_at IS NULL THEN NULL ELSE to_char((e.captured_at AT TIME ZONE '{{city:timezone}}'), 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_part('microseconds', (e.captured_at AT TIME ZONE '{{city:timezone}}'))::bigint % 1000000 = 0 THEN '' ELSE '.' || rtrim(to_char((e.captured_at AT TIME ZONE '{{city:timezone}}'), 'US'), '0') END || CASE WHEN ((e.captured_at AT TIME ZONE '{{city:timezone}}') - (e.captured_at AT TIME ZONE 'UTC')) < interval '0' THEN '-' || to_char(-((e.captured_at AT TIME ZONE '{{city:timezone}}') - (e.captured_at AT TIME ZONE 'UTC')), 'HH24:MI') ELSE '+' || to_char(((e.captured_at AT TIME ZONE '{{city:timezone}}') - (e.captured_at AT TIME ZONE 'UTC')), 'HH24:MI') END END, 'camera_id', e.camera_id, 'vision', e.vision) ORDER BY e.evidence_id) FROM public.evidence_media e WHERE e.crime_id = c.crime_id)::text, '[]') AS evidence, coalesce((SELECT json_agg(json_build_object('forensic_id', f.forensic_id, 'kind', f.kind, 'match_code', f.match_code) ORDER BY f.forensic_id) FROM public.forensics f WHERE f.crime_id = c.crime_id)::text, '[]') AS forensics, (SELECT json_build_object('extractor_version', cf.extractor_version, 'model', cf.model, 'receipt_id', cf.receipt_id, 'mo', cf.mo, 'visual_tags', to_json(cf.visual_tags), 'entities', cf.entities, 'confidence', cf.confidence, 'reviewed_by_officer', cf.reviewed_by IS NOT NULL)::text FROM public.crime_features cf WHERE cf.crime_id = c.crime_id ORDER BY cf.extractor_version DESC LIMIT 1) AS features FROM public.crimes c;
